#!/usr/bin/env node
// === adapter-dsl emitter — 1:1 restoration of old codegen (AggregateAdapterBuilder) ===
// Generates: <Name>SnapshotAdapter + <Name>EventAdapter
// Usage: node emit.mjs <spec.json> <out-dir>
//
// Golden shape (ingested-app *EventAdapter.scala / *SnapshotAdapter.scala):
//   - header: // @generated by CodegenMain:225ed28b + // @knowledge-release 1.0.0
//     (NO @knowledge comments anywhere in adapters — verified across all 27 aggregates)
//   - per-event imports (alphabetical, incl. the <Name>Event base type) in the event
//     adapter; the snapshot adapter duplicates the akka SnapshotAdapter import (golden bug, kept)
//   - PO imports from the aggregate's own proto package: protoPackage + "." + snake(name)
//   - cases delegate to the converters-trait Conv objects; blank-line rhythm is fixed
//     (2 blank lines between class members/cases, 3 blank lines around fromJournal)

import { readFileSync, writeFileSync, mkdirSync } from "fs";
import { join } from "path";

const [specPath, outDir] = process.argv.slice(2);
const spec = JSON.parse(readFileSync(specPath, "utf8"));
mkdirSync(outDir, { recursive: true });

const HEADER = `// @generated by CodegenMain:225ed28b
// @knowledge-release 1.0.0
`;
const pkg = spec.package || "net.imadz.metarch.infrastructure.persistence";
const name = spec.name;
const stateType = spec.stateType || `${name}State`;
const eventType = spec.eventType || `${name}Event`;
const convertersTrait = `${name}ProtoConverters`;
const entityPkg = spec.entityPackage || "net.imadz.metarch.domain.entities";
const convertersPkg = spec.convertersPackage || "net.imadz.metarch.infrastructure.persistence.converters";
const protoBase = spec.protoPackage || "net.imadz.metarch.infrastructure.proto";
const statePOType = spec.protoStateType || `${stateType}PO`;
const eventPOType = spec.protoEventType || `${eventType}PO`;

// deterministic across locales (golden orderings are codepoint)
const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
const snake = (s) =>
  s
    .replace(/([A-Z]+)([A-Z][a-z])/g, "$1_$2")
    .replace(/([a-z0-9])([A-Z])/g, "$1_$2")
    .toLowerCase();
const aggProtoPkg = `${protoBase}.${snake(name)}`;

// Cases + imports are emitted alphabetically by event name (golden), not in spec order.
const events = (spec.events || []).slice().sort((a, b) => cmp(a.name, b.name));

// ─── SnapshotAdapter ───
const snapshot = `${HEADER}package ${pkg}

import akka.persistence.typed.SnapshotAdapter
import akka.persistence.typed.SnapshotAdapter
import ${entityPkg}.${name}Entity.${stateType}
import ${convertersPkg}.${convertersTrait}
import ${aggProtoPkg}.${statePOType}

/**
 * ${name}SnapshotAdapter: 快照适配器，负责在领域快照和protobuf快照之间进行转换
 */
class ${name}SnapshotAdapter extends SnapshotAdapter[${stateType}] with ${convertersTrait} {



  override def toJournal(state: ${stateType}): Any = {
    ${stateType}Conv.toProto(state)
  }



  override def fromJournal(from: Any): ${stateType} = {
    val proto = from.asInstanceOf[${statePOType}]
    ${stateType}Conv.fromProto(proto)
  }



}
`;

// ─── EventAdapter ───
const entityImports = [eventType, ...events.map((e) => e.name)]
  .sort(cmp)
  .map((n) => `import ${entityPkg}.${name}Entity.${n}`)
  .join("\n");

const eventCases = events
  .map(
    (e) => `      case evt: ${e.name} =>
        ${eventPOType}.Event.${e.name}(${e.name}Conv.toProto(evt))`
  )
  .join("\n\n\n");

const fromCases = [
  ...events.map(
    (e) => `      case ${eventPOType}.Event.${e.name}(po) =>
        EventSeq.single(${e.name}Conv.fromProto(po))`
  ),
  `      case ${eventPOType}.Event.Empty =>
        EventSeq.empty`,
].join("\n\n\n");

const eventAdapter = `${HEADER}package ${pkg}

import akka.persistence.typed.EventAdapter
import akka.persistence.typed.EventSeq
${entityImports}
import ${convertersPkg}.${convertersTrait}
import ${aggProtoPkg}.${eventPOType}
import ${aggProtoPkg}.${eventPOType}.Event

/**
 * ${name}EventAdapter: 事件适配器，负责在领域事件和protobuf事件之间进行转换
 */
class ${name}EventAdapter extends EventAdapter[${eventType}, ${eventPOType}.Event] with ${convertersTrait} {


  override def manifest(event: ${eventType}): String = event.getClass.getName


  override def toJournal(e: ${eventType}): ${eventPOType}.Event = {
    val eventUnion = e match {

${eventCases}

    }
    eventUnion
  }



  override def fromJournal(p: ${eventPOType}.Event, manifest: String): EventSeq[${eventType}] = {
    p match {

${fromCases}
    }
  }



}
`;

writeFileSync(join(outDir, `${name}SnapshotAdapter.scala`), snapshot);
writeFileSync(join(outDir, `${name}EventAdapter.scala`), eventAdapter);
console.log(`emitted ${name}SnapshotAdapter.scala, ${name}EventAdapter.scala`);
